#nullable enable // autogenerated

using MVZ2.Vanilla.Entities;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Effects
{
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.blownAwayByWind)]
    public class BlownAwayByWind : EntityBehaviourDefinition, IBeBlownBehaviour
    {
        public BlownAwayByWind(string nsp, string name) : base(nsp, name)
        {
        }
        public void BeBlown(Entity entity, Entity source)
        {
            var newVelocity = source.GetFacingDirection();
            newVelocity *= entity.Velocity.magnitude;
            entity.Velocity = newVelocity;
        }
    }
}